import re
import struct
import sys
import zlib
from pathlib import Path

RECORD = re.compile(rb'([a-z0-9]+) line (0|[1-9][0-9]*) ratio 0\.([0-9]{6}) select pick win seed (0|[1-9][0-9]*)\n')
HEX = re.compile(rb'[0-9a-f]{96}\n')
BASE = re.compile(rb'[0-9a-z]{64}\n')
ALPHABET = b'0123456789abcdefghijklmnopqrstuvwxyz'


def pack(values, radix):
    value = 0
    for v in values:
        value = value * radix + v
    return value.to_bytes((value.bit_length() + 7) // 8, 'big')


def unpack(data, count, radix):
    value = int.from_bytes(data, 'big')
    out = [0] * count
    for i in range(count - 1, -1, -1):
        value, out[i] = divmod(value, radix)
    if value:
        raise ValueError('invalid integer stream')
    return out


def encode(data):
    tags, hexes = bytearray(), bytearray()
    bases, numbers = [], []
    prefix = None
    for line in data.splitlines(keepends=True):
        match = RECORD.fullmatch(line)
        if match:
            p, a, b, c = match.groups()
            if len(a) > 6 or len(c) > 9:
                return None
            if prefix is None:
                prefix = p
            if p != prefix:
                return None
            tags.append(2)
            numbers.append((int(a) * 10**6 + int(b)) * 10**9 + int(c))
        elif HEX.fullmatch(line):
            tags.append(0)
            hexes.extend(bytes.fromhex(line.decode('ascii')))
        elif BASE.fullmatch(line):
            tags.append(1)
            bases.append(int(line, 36))
        else:
            return None
    parts = [prefix or b'', zlib.compress(bytes(tags), 9), bytes(hexes),
             pack(bases, 36**64), pack(numbers, 10**21)]
    return struct.pack('>5I', *map(len, parts)) + b''.join(parts)


