        elif tag == 2:
            ab, c = divmod(next(numbers), 10**9)
            a, b = divmod(ab, 10**6)
            out.append(prefix + (' line %d ratio 0.%06d select pick win seed %d\n' % (a, b, c)).encode())
        else:
            raise ValueError('invalid record tag')
    return b''.join(out)


